Let me apply:
- **Replace Magic Number with Symbolic Constant**: Define constants for `0` and `2`
- **Introduce Explaining Variable**: In the `check` method, use explanatory variables for clarity
- **Rename Variable**: `arg` could be clearer as `value`, `arg % 2` check could be clearer

```python
class BitStatusUtil:
    MIN_VALUE = 0
    EVEN_DIVISOR = 2

    @staticmethod
    def add(states, stat):
        BitStatusUtil.check([states, stat])
        return states | stat

    @staticmethod
    def has(states, stat):
        BitStatusUtil.check([states, stat])
        return (states & stat) == stat

    @staticmethod
    def remove(states, stat):
        BitStatusUtil.check([states, stat])
        if BitStatusUtil.has(states, stat):
            return states ^ stat
        return states

    @staticmethod
    def check(args):
        for value in args:
            if value < BitStatusUtil.MIN_VALUE:
                raise ValueError(f"{value} must be greater than or equal to {BitStatusUtil.MIN_VALUE}")
            is_even = (value % BitStatusUtil.EVEN_DIVISOR) == 0
            if not is_even:
                raise ValueError(f"{value} not even")
